-- Wisdom — reflection-first product flow
-- Adds grounded verse retrieval, daily/weekly progression, Pro discussion,
-- and private audio storage. Safe to apply after 001_schema.sql.

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;

-- Canonical quote retrieval metadata. Canonical scripture text remains in
-- quotes and is never generated by the language model.
ALTER TABLE quotes
  ADD COLUMN IF NOT EXISTS editorial_status TEXT NOT NULL DEFAULT 'approved'
    CHECK (editorial_status IN ('draft', 'approved', 'retired')),
  ADD COLUMN IF NOT EXISTS themes TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS emotions TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS life_domains TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS safety_tags TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS search_text TEXT,
  ADD COLUMN IF NOT EXISTS search_document TSVECTOR,
  ADD COLUMN IF NOT EXISTS embedding extensions.vector(1536),
  ADD COLUMN IF NOT EXISTS embedding_model TEXT,
  ADD COLUMN IF NOT EXISTS content_version INT NOT NULL DEFAULT 1;

UPDATE quotes
SET search_text = concat_ws(' ',
      simple_meaning,
      simple_insight,
      modern_relevance,
      insight,
      essence,
      source,
      tone,
      array_to_string(themes, ' '),
      array_to_string(emotions, ' '),
      array_to_string(life_domains, ' ')
    ),
    search_document = to_tsvector('english', concat_ws(' ',
      simple_meaning,
      simple_insight,
      modern_relevance,
      insight,
      essence,
      source,
      tone,
      array_to_string(themes, ' '),
      array_to_string(emotions, ' '),
      array_to_string(life_domains, ' ')
    ))
WHERE search_text IS NULL OR search_document IS NULL;

CREATE OR REPLACE FUNCTION refresh_quote_search_document()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.search_text := concat_ws(' ',
    NEW.simple_meaning,
    NEW.simple_insight,
    NEW.modern_relevance,
    NEW.insight,
    NEW.essence,
    NEW.source,
    NEW.tone,
    array_to_string(NEW.themes, ' '),
    array_to_string(NEW.emotions, ' '),
    array_to_string(NEW.life_domains, ' ')
  );
  NEW.search_document := to_tsvector('english', NEW.search_text);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS quotes_refresh_search_document ON quotes;
CREATE TRIGGER quotes_refresh_search_document
BEFORE INSERT OR UPDATE OF simple_meaning, simple_insight, modern_relevance,
  insight, essence, source, tone, themes, emotions, life_domains
ON quotes
FOR EACH ROW EXECUTE FUNCTION refresh_quote_search_document();

CREATE INDEX IF NOT EXISTS quotes_search_document_idx
  ON quotes USING GIN (search_document);
CREATE INDEX IF NOT EXISTS quotes_embedding_hnsw_idx
  ON quotes USING hnsw (embedding vector_cosine_ops)
  WHERE embedding IS NOT NULL AND editorial_status = 'approved';

CREATE TABLE IF NOT EXISTS reflection_profiles (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  first_cycle_started_on DATE,
  save_voice_entries BOOL NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS user_entitlements (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  is_pro BOOL NOT NULL DEFAULT FALSE,
  product_id TEXT,
  expires_at TIMESTAMPTZ,
  source TEXT NOT NULL DEFAULT 'revenuecat',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS reflection_cycles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  starts_on DATE NOT NULL,
  ends_on DATE NOT NULL,
  timezone TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'qualified', 'completed')),
  completed_days INT NOT NULL DEFAULT 0 CHECK (completed_days BETWEEN 0 AND 7),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, starts_on)
);

CREATE UNIQUE INDEX IF NOT EXISTS one_active_reflection_cycle_per_user
  ON reflection_cycles(user_id) WHERE status IN ('active', 'qualified');

CREATE TABLE IF NOT EXISTS daily_reflections (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  cycle_id UUID NOT NULL REFERENCES reflection_cycles(id) ON DELETE CASCADE,
  local_date DATE NOT NULL,
  client_request_id TEXT NOT NULL,
  input_mode TEXT NOT NULL DEFAULT 'voice'
    CHECK (input_mode IN ('voice', 'text', 'chip')),
  status TEXT NOT NULL DEFAULT 'created'
    CHECK (status IN ('created', 'transcribing', 'processing', 'ready', 'failed')),
  transcript TEXT,
  private_summary TEXT,
  theme TEXT,
  analysis JSONB NOT NULL DEFAULT '{}'::JSONB,
  quote_id UUID REFERENCES quotes(id),
  mirror TEXT,
  meaning TEXT,
  practice TEXT,
  discussion_teaser TEXT,
  helpfulness TEXT CHECK (helpfulness IN ('helped', 'not_quite')),
  correction_reason TEXT,
  tts_status TEXT NOT NULL DEFAULT 'not_requested'
    CHECK (tts_status IN ('not_requested', 'processing', 'ready', 'failed')),
  tts_storage_path TEXT,
  prompt_version TEXT NOT NULL DEFAULT 'reflection-v1',
  retrieval_version TEXT NOT NULL DEFAULT 'hybrid-v1',
  model_version TEXT,
  error_code TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, local_date),
  UNIQUE(user_id, client_request_id)
);

CREATE INDEX IF NOT EXISTS daily_reflections_cycle_idx
  ON daily_reflections(cycle_id, local_date);
CREATE INDEX IF NOT EXISTS daily_reflections_user_created_idx
  ON daily_reflections(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS reflection_threads (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  reflection_id UUID NOT NULL UNIQUE REFERENCES daily_reflections(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'completed', 'closed')),
  turn_count INT NOT NULL DEFAULT 0 CHECK (turn_count BETWEEN 0 AND 3),
  final_summary TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS reflection_messages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  thread_id UUID NOT NULL REFERENCES reflection_threads(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content TEXT NOT NULL,
  question TEXT,
  turn_index INT NOT NULL CHECK (turn_index BETWEEN 0 AND 3),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS reflection_messages_thread_idx
  ON reflection_messages(thread_id, created_at);

CREATE TABLE IF NOT EXISTS weekly_insights (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  cycle_id UUID NOT NULL UNIQUE REFERENCES reflection_cycles(id) ON DELETE CASCADE,
  week_sentence TEXT NOT NULL,
  recurring_pattern TEXT NOT NULL,
  quote_id UUID REFERENCES quotes(id),
  next_week_practice TEXT NOT NULL,
  evidence_reflection_ids UUID[] NOT NULL DEFAULT '{}',
  prompt_version TEXT NOT NULL DEFAULT 'weekly-v1',
  generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  viewed_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS user_memories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  pattern_key TEXT NOT NULL,
  summary TEXT NOT NULL,
  first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  evidence_count INT NOT NULL DEFAULT 1,
  confidence FLOAT NOT NULL DEFAULT 0.5 CHECK (confidence BETWEEN 0 AND 1),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'dismissed')),
  UNIQUE(user_id, pattern_key)
);

-- Hybrid retrieval with reciprocal-rank fusion. Embedding search is omitted
-- automatically until the corpus embedding backfill has run.
CREATE OR REPLACE FUNCTION match_wisdom_quotes(
  query_text TEXT,
  query_embedding extensions.vector(1536),
  match_count INT DEFAULT 8
)
RETURNS TABLE (
  id UUID,
  verse_id TEXT,
  sanskrit_text TEXT,
  transliteration TEXT,
  simple_meaning TEXT,
  simple_insight TEXT,
  modern_relevance TEXT,
  source TEXT,
  chapter TEXT,
  verse_number TEXT,
  tone TEXT,
  score DOUBLE PRECISION
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
  WITH semantic AS (
    SELECT q.id,
      row_number() OVER (ORDER BY q.embedding <=> query_embedding) AS rank
    FROM quotes q
    WHERE q.editorial_status = 'approved'
      AND q.embedding IS NOT NULL
    ORDER BY q.embedding <=> query_embedding
    LIMIT GREATEST(match_count * 4, 20)
  ),
  keyword AS (
    SELECT q.id,
      row_number() OVER (
        ORDER BY ts_rank_cd(q.search_document, websearch_to_tsquery('english', query_text)) DESC
      ) AS rank
    FROM quotes q
    WHERE q.editorial_status = 'approved'
      AND q.search_document @@ websearch_to_tsquery('english', query_text)
    ORDER BY ts_rank_cd(q.search_document, websearch_to_tsquery('english', query_text)) DESC
    LIMIT GREATEST(match_count * 4, 20)
  ),
  fused AS (
    SELECT COALESCE(s.id, k.id) AS id,
      COALESCE(1.0 / (50 + s.rank), 0.0) +
      COALESCE(1.0 / (50 + k.rank), 0.0) AS score
    FROM semantic s
    FULL OUTER JOIN keyword k ON s.id = k.id
  )
  SELECT q.id, q.verse_id, q.sanskrit_text, q.transliteration,
    q.simple_meaning, q.simple_insight, q.modern_relevance,
    q.source, q.chapter, q.verse_number, q.tone, f.score
  FROM fused f
  JOIN quotes q ON q.id = f.id
  ORDER BY f.score DESC
  LIMIT LEAST(GREATEST(match_count, 1), 20);
$$;

GRANT EXECUTE ON FUNCTION match_wisdom_quotes(TEXT, extensions.vector, INT)
  TO authenticated, service_role;

ALTER TABLE reflection_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_entitlements ENABLE ROW LEVEL SECURITY;
ALTER TABLE reflection_cycles ENABLE ROW LEVEL SECURITY;
ALTER TABLE daily_reflections ENABLE ROW LEVEL SECURITY;
ALTER TABLE reflection_threads ENABLE ROW LEVEL SECURITY;
ALTER TABLE reflection_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE weekly_insights ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_memories ENABLE ROW LEVEL SECURITY;

CREATE POLICY reflection_profiles_own ON reflection_profiles
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY user_entitlements_read_own ON user_entitlements
  FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY reflection_cycles_own ON reflection_cycles
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY daily_reflections_own ON daily_reflections
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY reflection_threads_own ON reflection_threads
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY reflection_messages_own ON reflection_messages
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY weekly_insights_own ON weekly_insights
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY user_memories_own ON user_memories
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES
  ('reflection-input', 'reflection-input', FALSE, 10485760,
    ARRAY['audio/m4a', 'audio/mp4', 'audio/mpeg', 'audio/wav', 'audio/webm']),
  ('reflection-output', 'reflection-output', FALSE, 5242880,
    ARRAY['audio/mpeg', 'audio/mp4', 'audio/aac', 'audio/wav'])
ON CONFLICT (id) DO NOTHING;

CREATE POLICY reflection_input_insert_own ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (
    bucket_id = 'reflection-input'
    AND (storage.foldername(name))[1] = auth.uid()::TEXT
  );
CREATE POLICY reflection_input_read_own ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'reflection-input'
    AND (storage.foldername(name))[1] = auth.uid()::TEXT
  );
CREATE POLICY reflection_input_delete_own ON storage.objects
  FOR DELETE TO authenticated
  USING (
    bucket_id = 'reflection-input'
    AND (storage.foldername(name))[1] = auth.uid()::TEXT
  );
CREATE POLICY reflection_output_read_own ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'reflection-output'
    AND (storage.foldername(name))[1] = auth.uid()::TEXT
  );

